verbraucherdarlehen_sollzinskorrektur <- function(vertraglicher_sollzinssatz=NULL,angegebener_effektiver_jahreszins=NULL,tatsaechlicher_effektiver_jahreszins=NULL,einordnungsnachweis=NULL) {
 soll <- .geld(vertraglicher_sollzinssatz); angegeben <- .geld(angegebener_effektiver_jahreszins); tatsaechlich <- .geld(tatsaechlicher_effektiver_jahreszins)
 .text(einordnungsnachweis,'einordnungsnachweis')
 if(.vergleichen(angegeben,tatsaechlich)>0) .fehler('angegebener_effektiver_jahreszins','Diese Korrektur verlangt h\u00f6chstens den tats\u00e4chlichen Effektivzins als Angabe.')
 differenz <- .subtrahieren(tatsaechlich,angegeben); korrigiert <- .subtrahieren(soll,differenz)
 wert <- list(effektivzins_unterangabe=.bruchteile(differenz),rechnerisch_verminderter_sollzinssatz=.bruchteile(korrigiert))
 eingaben <- list(vertraglicher_sollzinssatz=vertraglicher_sollzinssatz,angegebener_effektiver_jahreszins=angegebener_effektiver_jahreszins,tatsaechlicher_effektiver_jahreszins=tatsaechlicher_effektiver_jahreszins,einordnungsnachweis=einordnungsnachweis)
 ergebnis <- .ergebnis(wert,'zinssaetze','BGB_VERBRAUCHERDARLEHEN_SOLLZINSKORREKTUR',eingaben,list(list(operation='Tats\u00e4chlicher Effektivzins minus angegebener Effektivzins als absolute Zinsdifferenz vom Sollzinssatz abziehen.')),eingaben)
 ergebnis$hinweise <- list("Nur \u00a7494 Absatz3 bei qualifiziert zu niedrig angegebenem effektivem Jahreszins. Zinss\u00e4tze als Jahresquoten eingeben, etwa0.05 f\u00fcr5Prozent; Differenz von6%und5% ist ein Prozentpunkt, kein relativer Abschlag von20%. Tats\u00e4chlichen Effektivzins extern nach einschl\u00e4gigen Vorgaben berechnen. Ergebnis ist der vorzeichenbehaftete mathematische Korrekturwert ohne im Normtext nicht genannte Nulluntergrenze; negative Ergebnisse begr\u00fcnden hier keine automatische Zahlungspflicht des Darlehensgebers. Fehlende Angaben nach Absatz2, Kostenwegfall nach Absatz4 und neue Raten nach Absatz5 separat behandeln; keine automatische Annuit\u00e4tenformel.")
 ergebnis
}
immobiliardarlehen_wechselkursrechnung <- function(fremdwaehrungsbetrag=NULL,wechselkurs_vertrag=NULL,wechselkurs_vergleich=NULL,wechselkurs_umstellung=NULL,einordnungsnachweis=NULL) {
 betrag <- .geld(fremdwaehrungsbetrag); vertrag <- .geld(wechselkurs_vertrag); vergleich <- .geld(wechselkurs_vergleich); umstellung <- .geld(wechselkurs_umstellung)
 .text(einordnungsnachweis,'einordnungsnachweis')
 if(.vergleichen(vertrag,.bruch(0))<=0 || .vergleichen(vergleich,.bruch(0))<=0 || .vergleichen(umstellung,.bruch(0))<=0) .fehler('wechselkurse','Alle Kurse m\u00fcssen positiv sein und Landesw\u00e4hrung je einer Fremdw\u00e4hrungseinheit ausdr\u00fccken.')
 vertragswert <- .multiplizieren(betrag,vertrag); vergleichswert <- .multiplizieren(betrag,vergleich); grenze <- .multiplizieren(vertragswert,.bruch(6,5)); umstellungswert <- .multiplizieren(betrag,umstellung)
 wert <- list(wert_zum_vertragskurs=.bruchteile(vertragswert),wert_zum_vergleichskurs=.bruchteile(vergleichswert),zwanzigprozent_grenzwert=.bruchteile(grenze),grenze_strikt_ueberschritten=.vergleichen(vergleichswert,grenze)>0,wert_zum_umstellungskurs=.bruchteile(umstellungswert))
 eingaben <- list(fremdwaehrungsbetrag=fremdwaehrungsbetrag,wechselkurs_vertrag=wechselkurs_vertrag,wechselkurs_vergleich=wechselkurs_vergleich,wechselkurs_umstellung=wechselkurs_umstellung,einordnungsnachweis=einordnungsnachweis)
 ergebnis <- .ergebnis(wert,'landeswaehrung','BGB_IMMOBILIARDARLEHEN_WECHSELKURSRECHNUNG',eingaben,list(list(operation='Denselben Fremdw\u00e4hrungsbetrag mit jeweils Landesw\u00e4hrung/Fremdw\u00e4hrung-Kurs multiplizieren; Vergleichswert strikt \u00fcber6/5 des Vertragskurswerts; Umstellung zum gesondert qualifizierten Kurs.')),eingaben)
 ergebnis$hinweise <- list("Nur \u00a7503 f\u00fcr qualifiziertes Immobiliar-Verbraucherdarlehen in Fremdw\u00e4hrung. Derselbe aktuelle Restbetrag oder dieselbe regelm\u00e4\u00dfige Rate wird in beiden Vergleichswerten verwendet, nicht urspr\u00fcnglicher Nennbetrag gegen heutige Restschuld. Landesw\u00e4hrung nach Absatz1 einschlie\u00dflich wirksamer W\u00e4hrungsvereinbarung rechtlich bestimmen. Restbetrag und Rate bei unterschiedlichen relevanten Werten separat pr\u00fcfen; numerischer Ausl\u00f6ser liegt vor, wenn wenigstens einer strikt \u00fcber20% gestiegen ist. Umstellungskurs ist grunds\u00e4tzlich Marktwechselkurs am Antragstag, bei wirksamer abweichender Vereinbarung deren Kurs; muss extern belegt werden. Kein Kursabruf, keine automatische Umwandlung/Vertrags\u00e4nderung. Alle Kurse haben dieselbe ausdr\u00fcckliche Orientierung Landesw\u00e4hrung je Fremdw\u00e4hrungseinheit.")
 ergebnis
}
